                    in_color = input_grid[i, j]
                    out_color = output_grid[i, j]
                    if in_color in color_mapping:
                        if color_mapping[in_color] != out_color:
                            consistent_mapping = False
                            break
                    else:
                        color_mapping[in_color] = out_color
                if not consistent_mapping:
